import json

def parse_progress(raw):
    if len(raw) > 200:
        raise ValueError('progress record is too large')
    try:
        record = json.loads(raw)
    except json.JSONDecodeError as error:
        raise ValueError('invalid progress JSON') from error
    if not isinstance(record, dict):
        raise ValueError('progress must be an object')
    if type(record.get('done')) is not int or not 0 <= record['done'] <= 100:
        raise ValueError('done must be an integer from 0 to 100')
    return record['done']

print(parse_progress('{"done": 4}'))
try:
    parse_progress('{"done": true}')
except ValueError:
    print('invalid field rejected')

